nvmlReturn_t nvmlSystemGetCudaDriverVersion(int * cudaDriverVersion) {
    // TraceCall("nvmlSystemGetCudaDriverVersion");
    nvmlReturn_t res = NVML_SUCCESS;

    if (!initialize() || g_interface.hgmlSystemGetHggcDriverVersion_ptr == NULL) {
        fprintf(stderr, "Initialize HGGC Api Failed: hgmlSystemGetHggcDriverVersion.\n");
        exit(1);
    }

    if ((g_profileHandler.isCallbackEnabled != NULL) &&
        g_profileHandler.isCallbackEnabled(g_profileDomain, nvidia_ml_TRACE_CBID_nvmlSystemGetCudaDriverVersion) != 0) {
        g_profileHandler.profileCallbackBegin(g_profileDomain, nvidia_ml_TRACE_CBID_nvmlSystemGetCudaDriverVersion);
        hgmlReturn_t __ret = g_interface.hgmlSystemGetHggcDriverVersion_ptr(cudaDriverVersion);

        g_profileHandler.profileCallbackEnd(g_profileDomain, nvidia_ml_TRACE_CBID_nvmlSystemGetCudaDriverVersion);
        res = (nvmlReturn_t)__ret;
    } else {
        hgmlReturn_t __ret = g_interface.hgmlSystemGetHggcDriverVersion_ptr(cudaDriverVersion);

        res = (nvmlReturn_t)__ret;
    }

    if (res == NVML_SUCCESS) {
        *cudaDriverVersion = CUDA_VERSION;
    }

    return res;
}

